console.log('init', await s());
await p.screenshot({path: '/tmp/pw/light.png'});
await p.mouse.move(500, 250); await p.waitForTimeout(300);
await p.screenshot({path: '/tmp/pw/hover.png'});
await p.waitForTimeout(4500);
console.log('after 4.5s', await s());
await p.evaluate(() => window.__setTheme('dark')); await p.waitForTimeout(300);
await p.mouse.move(700, 200); await p.waitForTimeout(300);
await p.screenshot({path: '/tmp/pw/dark.png'});
// zoom by drag
await p.mouse.move(400, 250); await p.mouse.down(); await p.mouse.move(600, 250, {steps: 5}); await p.mouse.up();
await p.waitForTimeout(300);
const xs = () => p.evaluate(() => { const y = window.__stats.instances.at(-1); const u = y.uplot; return {min: u.scales.x.min, max: u.scales.x.max, d0: u.data[0][0], dN: u.data[0].at(-1), btnDisabled: document.querySelector('.cpu-load-chart button').disabled}; });
console.log('zoomed', await xs());
await p.waitForTimeout(4500);
console.log('zoom after updates', await xs(), await s());
await p.mouse.move(800, 100);
await p.screenshot({path: '/tmp/pw/zoom.png'});
await p.click('.cpu-load-chart button'); await p.waitForTimeout(200);
console.log('reset', await xs());
await p.evaluate(() => window.__setWidth(600)); await p.waitForTimeout(300);
console.log('resized', await s());
await p.evaluate(() => window.__setMounted(false)); await p.waitForTimeout(300);
console.log('unmounted', await s());
await p.waitForTimeout(2500);
console.log('later', await s());
console.log('errors', errs);
await b.close();
EOF
